import type { WritingSample } from '@/data/writing-samples';

type ParagraphSeed = { en: string; vi: string; focusVi: string };
type AdvantageSeed = {
  id: string;
  topicSlug: string;
  topicEn: string;
  topicVi: string;
  title: string;
  promptText: string;
  paragraphs: [ParagraphSeed, ParagraphSeed, ParagraphSeed, ParagraphSeed];
  vocabulary: WritingSample['vocabulary'];
};

const SECTIONS = ['introduction', 'body1', 'body2', 'conclusion'] as const;

function makeAdvantageSample(seed: AdvantageSeed): WritingSample {
  return {
    ...seed,
    task: 'ielts_task2',
    essayKind: 'advantage_disadvantage',
    promptId: `w-${seed.id}`,
    // Learning label only; this band has not been independently assessed.
    band: 8.0,
    paragraphs: seed.paragraphs.map((part, index) => ({
      id: `${seed.id}-p${index + 1}`,
      section: SECTIONS[index]!,
      ...part,
    })),
  };
}

const SEEDS: AdvantageSeed[] = [
  {
    id: 'sample-t2-extra-advantages-education', topicSlug: 'education', topicEn: 'Education', topicVi: 'Giáo dục',
    title: 'Online courses in higher education',
    promptText: 'Many universities now offer degree courses that students can complete online instead of attending classes on campus. Do the advantages of this development outweigh the disadvantages?',
    paragraphs: [
      { en: 'Universities increasingly allow students to earn degrees through online courses rather than attending a campus every day. This format can make higher education more accessible and flexible, although it may weaken the social and practical parts of learning. On balance, I believe its advantages are greater when courses are designed to include regular interaction and appropriate hands-on work.', vi: 'Ngày càng nhiều trường đại học cho phép sinh viên lấy bằng qua các khoá học trực tuyến thay vì phải đến trường mỗi ngày. Hình thức này có thể giúp giáo dục bậc cao dễ tiếp cận và linh hoạt hơn, dù có thể làm suy yếu khía cạnh xã hội và thực hành của việc học. Nhìn chung, tôi cho rằng lợi ích lớn hơn nếu chương trình có tương tác thường xuyên và phần thực hành phù hợp.', focusVi: 'Mở bài diễn đạt lại xu hướng, thừa nhận mặt hạn chế và nêu kết luận so sánh.' },
      { en: 'The clearest benefit is that geography and daily schedules become less decisive. A learner in a rural area can study with a university in another city without relocating, while people with jobs or caring duties can watch recorded lectures at convenient times. This can reduce travel and housing costs as well as widen access for students whose circumstances would otherwise prevent enrolment. Digital materials can also be revisited, allowing learners to pause difficult explanations and review them before an assessment.', vi: 'Lợi ích rõ nhất là địa lý và lịch sinh hoạt không còn quyết định nhiều như trước. Người học ở vùng nông thôn có thể học tại trường ở thành phố khác mà không cần chuyển chỗ ở, còn người đi làm hoặc có trách nhiệm chăm sóc gia đình có thể xem bài giảng đã ghi vào thời gian phù hợp. Điều này có thể giảm chi phí đi lại, nhà ở và mở rộng cơ hội cho những người khó theo học vì hoàn cảnh. Tài liệu số cũng có thể xem lại, giúp người học dừng ở phần khó và ôn trước kỳ đánh giá.', focusVi: 'Thân bài 1 giải thích lợi ích về khả năng tiếp cận, chi phí và nhịp học.' },
      { en: 'However, a screen cannot fully reproduce the focus and community of a classroom. Students may feel isolated, postpone assignments and miss informal conversations that help them test ideas. Some subjects also require laboratories, studios or supervised practice, which cannot safely be replaced by videos. These drawbacks are serious, but they are not inevitable: universities can schedule live seminars, peer projects and short in-person sessions, while reserving online delivery for material suited to independent study.', vi: 'Tuy nhiên, màn hình không thể tái tạo đầy đủ sự tập trung và cộng đồng của lớp học. Sinh viên có thể cảm thấy cô lập, trì hoãn bài tập và bỏ lỡ những cuộc trò chuyện không chính thức giúp họ thử nghiệm ý tưởng. Một số ngành còn cần phòng thí nghiệm, xưởng thực hành hoặc hoạt động có giám sát mà video không thể thay thế an toàn. Những hạn chế này đáng kể nhưng không phải không thể khắc phục: trường có thể tổ chức hội thảo trực tiếp, dự án nhóm và các buổi gặp ngắn, đồng thời dùng hình thức trực tuyến cho nội dung phù hợp với việc tự học.', focusVi: 'Thân bài 2 nêu bất lợi rồi chỉ ra cách thiết kế có thể hạn chế chúng.' },
      { en: 'Online degrees should not be treated as a universal replacement for campus study, particularly in practice-heavy disciplines. Nevertheless, their ability to bring qualified teaching within reach of people with limited time, money or mobility is substantial. If universities build in meaningful contact and practical components, flexible online provision offers more educational opportunity than it removes.', vi: 'Không nên xem bằng cấp trực tuyến là sự thay thế phổ quát cho việc học tại trường, nhất là ở những ngành thiên về thực hành. Dù vậy, khả năng đưa giảng dạy chất lượng đến với người hạn chế về thời gian, tiền bạc hoặc khả năng di chuyển là rất đáng kể. Nếu trường đại học tạo cơ hội tương tác có ý nghĩa và thành phần thực hành, hình thức trực tuyến linh hoạt sẽ mở ra nhiều cơ hội học tập hơn là lấy đi.', focusVi: 'Kết luận nhắc điều kiện áp dụng và khẳng định lợi ích tổng thể.' },
    ],
    vocabulary: [
      { phrase: 'higher education', meaningVi: 'giáo dục bậc cao', noteVi: 'Cụm khái quát cho học tập sau bậc phổ thông.' },
      { phrase: 'hands-on work', meaningVi: 'công việc thực hành trực tiếp', noteVi: 'Dùng khi phân biệt thực hành với học lý thuyết.' },
      { phrase: 'widen access', meaningVi: 'mở rộng khả năng tiếp cận', noteVi: 'Kết hợp tự nhiên với education, training hoặc services.' },
    ],
  },
  {
    id: 'sample-t2-extra-advantages-environment', topicSlug: 'environment', topicEn: 'Environment', topicVi: 'Môi trường',
    title: 'Expanding wind and solar power',
    promptText: 'Countries are investing more heavily in wind and solar power to meet their energy needs. Do the advantages of this shift outweigh its disadvantages?',
    paragraphs: [
      { en: 'Wind farms and solar panels are becoming more common as countries seek alternatives to fossil fuels. Expanding these sources involves costs and can alter local landscapes, yet it also reduces pollution and reliance on fuels that are finite. In my view, the environmental and security gains outweigh the disadvantages, provided new projects are planned with communities and supported by reliable storage and grid capacity.', vi: 'Trang trại gió và tấm pin mặt trời ngày càng phổ biến khi các quốc gia tìm nguồn thay thế nhiên liệu hoá thạch. Mở rộng các nguồn này đòi hỏi chi phí và có thể làm thay đổi cảnh quan địa phương, nhưng cũng giảm ô nhiễm và sự phụ thuộc vào nhiên liệu hữu hạn. Theo tôi, lợi ích về môi trường và an ninh năng lượng lớn hơn bất lợi, miễn là dự án được quy hoạch cùng cộng đồng và có hệ thống lưu trữ, lưới điện đáng tin cậy.', focusVi: 'Mở bài giới thiệu chuyển dịch năng lượng, cân nhắc hai phía và nêu điều kiện cho lập trường.' },
      { en: 'Unlike coal or gas, sunlight and wind do not release carbon dioxide while generating electricity. Their use can therefore lower emissions and improve air quality, particularly when they replace older, heavily polluting power stations. They also diversify a country’s energy supply: importing less fuel can reduce exposure to price shocks or interruptions abroad. Although turbines and panels require minerals and energy to manufacture, they can produce power for decades, spreading that initial environmental cost across a long operating life.', vi: 'Khác với than hay khí đốt, ánh nắng và gió không thải khí carbon dioxide trong lúc tạo điện. Vì vậy, việc sử dụng chúng có thể giảm phát thải và cải thiện chất lượng không khí, đặc biệt khi thay thế nhà máy điện cũ gây ô nhiễm nặng. Chúng cũng đa dạng hoá nguồn cung: nhập khẩu ít nhiên liệu hơn có thể giảm tác động của cú sốc giá hay gián đoạn ở nước ngoài. Dù tuabin và tấm pin cần khoáng sản, năng lượng để sản xuất, chúng có thể tạo điện trong nhiều thập kỷ, phân bổ chi phí môi trường ban đầu trên thời gian vận hành dài.', focusVi: 'Thân bài 1 phát triển lợi ích khí hậu, sức khoẻ và an ninh năng lượng.' },
      { en: 'The main difficulty is that output varies with weather and time of day. A region may need backup generation, batteries or stronger connections to neighbouring grids, all of which require investment. Large installations can also compete with farms or disturb habitats, and nearby residents may object to noise or views. These concerns call for careful site selection and fair consultation rather than abandoning the transition. Storage technology and a mix of renewable sources can further smooth fluctuations in supply.', vi: 'Khó khăn chính là sản lượng thay đổi theo thời tiết và thời điểm trong ngày. Một khu vực có thể cần nguồn điện dự phòng, pin lưu trữ hoặc kết nối mạnh hơn với lưới điện lân cận, tất cả đều cần đầu tư. Công trình lớn cũng có thể cạnh tranh đất nông nghiệp hoặc ảnh hưởng sinh cảnh, còn cư dân gần đó có thể phản đối tiếng ồn hay cảnh quan. Những lo ngại này cần được giải quyết bằng lựa chọn địa điểm cẩn trọng và tham vấn công bằng, thay vì từ bỏ quá trình chuyển đổi. Công nghệ lưu trữ và kết hợp nhiều nguồn tái tạo có thể làm nguồn cung ổn định hơn.', focusVi: 'Thân bài 2 nêu hạn chế về tính ổn định, sử dụng đất và phản ứng cộng đồng.' },
      { en: 'Renewable power is not impact-free, and governments should account for the materials, land and infrastructure it requires. Even so, these costs are manageable through sound planning and are outweighed by lower pollution and reduced dependence on imported fuels. A gradual expansion that invests in storage and respects local needs is a more durable energy strategy than continued reliance on fossil sources.', vi: 'Điện tái tạo không hoàn toàn không gây tác động, và chính phủ cần tính đến vật liệu, đất đai cùng hạ tầng cần thiết. Dẫu vậy, các chi phí này có thể quản lý bằng quy hoạch hợp lý và nhỏ hơn lợi ích giảm ô nhiễm, giảm lệ thuộc vào nhiên liệu nhập khẩu. Mở rộng dần, đầu tư lưu trữ và tôn trọng nhu cầu địa phương là chiến lược năng lượng bền vững hơn việc tiếp tục dựa vào nhiên liệu hoá thạch.', focusVi: 'Kết luận cân đối chi phí thực tế với lợi ích dài hạn và nhấn mạnh cách triển khai.' },
    ],
    vocabulary: [
      { phrase: 'fossil fuels', meaningVi: 'nhiên liệu hoá thạch', noteVi: 'Cụm chỉ than đá, dầu mỏ và khí tự nhiên.' },
      { phrase: 'energy supply', meaningVi: 'nguồn cung năng lượng', noteVi: 'Cụm danh từ thường dùng trong thảo luận chính sách.' },
      { phrase: 'site selection', meaningVi: 'việc lựa chọn địa điểm', noteVi: 'Hữu ích khi bàn về quy hoạch công trình.' },
    ],
  },
  {
    id: 'sample-t2-extra-advantages-technology', topicSlug: 'technology', topicEn: 'Technology', topicVi: 'Công nghệ',
    title: 'The move towards cashless payments',
    promptText: 'In many places, people are using cards and mobile apps instead of cash for everyday purchases. Do the advantages of this development outweigh the disadvantages?',
    paragraphs: [
      { en: 'Digital payments have become routine in shops, on public transport and between friends. They can make transactions quicker and easier to track, but reliance on electronic systems creates privacy and access concerns. Overall, I consider the shift beneficial, as long as cash remains available and payment providers protect users’ data and provide dependable services.', vi: 'Thanh toán số đã trở nên thường nhật ở cửa hàng, trên phương tiện công cộng và giữa bạn bè. Hình thức này có thể giúp giao dịch nhanh hơn và dễ theo dõi, nhưng phụ thuộc vào hệ thống điện tử làm nảy sinh lo ngại về quyền riêng tư và khả năng tiếp cận. Nhìn chung, tôi cho rằng xu hướng này có lợi nếu tiền mặt vẫn được sử dụng và nhà cung cấp bảo vệ dữ liệu, duy trì dịch vụ ổn định.', focusVi: 'Mở bài nêu các mặt chính và lập trường có điều kiện.' },
      { en: 'For consumers, tapping a card or phone is convenient and avoids carrying exact change. A digital record can help people review spending, split bills and identify unfamiliar transactions. Businesses may benefit too: handling less cash reduces time spent counting tills and the risk of theft, while online payment can serve customers who shop remotely. These efficiencies matter most in busy settings, where small delays accumulate, and they can make routine purchases smoother for both sellers and buyers.', vi: 'Với người tiêu dùng, chạm thẻ hoặc điện thoại rất tiện lợi và tránh phải mang tiền lẻ. Hồ sơ giao dịch số giúp mọi người xem lại chi tiêu, chia hoá đơn và nhận ra khoản thanh toán lạ. Doanh nghiệp cũng có thể hưởng lợi: xử lý ít tiền mặt giảm thời gian kiểm đếm quầy và nguy cơ trộm cắp, trong khi thanh toán trực tuyến phục vụ khách mua từ xa. Hiệu quả này đặc biệt hữu ích ở nơi đông khách, khi những chậm trễ nhỏ cộng dồn, giúp giao dịch thường ngày thuận tiện hơn cho cả người bán lẫn người mua.', focusVi: 'Thân bài 1 trình bày sự tiện lợi và lợi ích quản lý cho cá nhân, doanh nghiệp.' },
      { en: 'Yet a fully cashless system could exclude people without bank accounts, smartphones or stable internet. Older residents and people with disabilities may also find some interfaces difficult to use. Digital records create another risk: payment data could be misused, leaked or used to profile customers. Technical outages can prevent purchases even when a person has sufficient funds. These are meaningful disadvantages, but they can be limited by keeping cash as an option, designing accessible services and requiring strong data safeguards.', vi: 'Tuy nhiên, hệ thống hoàn toàn không dùng tiền mặt có thể loại trừ người không có tài khoản ngân hàng, điện thoại thông minh hoặc mạng ổn định. Người lớn tuổi và người khuyết tật cũng có thể thấy một số giao diện khó sử dụng. Hồ sơ số tạo thêm rủi ro: dữ liệu thanh toán có thể bị lạm dụng, rò rỉ hoặc dùng để lập hồ sơ khách hàng. Sự cố kỹ thuật có thể ngăn mua hàng dù người mua đủ tiền. Đây là những bất lợi đáng kể, nhưng có thể hạn chế bằng cách duy trì tiền mặt, thiết kế dịch vụ dễ tiếp cận và yêu cầu bảo vệ dữ liệu nghiêm ngặt.', focusVi: 'Thân bài 2 phân tích nguy cơ loại trừ, riêng tư và gián đoạn kỹ thuật, sau đó đưa giải pháp.' },
      { en: 'The move to digital payment is valuable because it reduces friction in everyday transactions and can improve financial oversight. Its benefits do not justify forcing every person to use technology, however. A system that combines secure digital options with cash access and resilient backup arrangements can capture the convenience without making participation dependent on a device or network.', vi: 'Chuyển sang thanh toán số có giá trị vì giảm trở ngại trong giao dịch hằng ngày và có thể cải thiện việc theo dõi tài chính. Tuy nhiên, lợi ích ấy không biện minh cho việc buộc mọi người phải dùng công nghệ. Một hệ thống kết hợp lựa chọn số an toàn với tiền mặt và phương án dự phòng vững chắc có thể giữ được sự tiện lợi mà không khiến việc tham gia phụ thuộc vào thiết bị hay mạng.', focusVi: 'Kết luận khẳng định lợi ích, đồng thời nêu nguyên tắc duy trì khả năng lựa chọn.' },
    ],
    vocabulary: [
      { phrase: 'digital record', meaningVi: 'hồ sơ kỹ thuật số', noteVi: 'Dùng để nói về dữ liệu được lưu lại tự động.' },
      { phrase: 'cashless system', meaningVi: 'hệ thống không dùng tiền mặt', noteVi: 'Cụm chỉ phương thức thanh toán hoàn toàn qua điện tử.' },
      { phrase: 'data safeguards', meaningVi: 'biện pháp bảo vệ dữ liệu', noteVi: 'Cụm danh từ phù hợp với quyền riêng tư trực tuyến.' },
    ],
  },
  {
    id: 'sample-t2-extra-advantages-health', topicSlug: 'health', topicEn: 'Health', topicVi: 'Sức khoẻ',
    title: 'Remote medical consultations',
    promptText: 'Patients can increasingly consult doctors through video calls rather than travelling to a clinic. Do the advantages of remote consultations outweigh their disadvantages?',
    paragraphs: [
      { en: 'Video consultations allow patients to speak with clinicians without first travelling to a medical centre. This approach can save time and bring advice to people far from healthcare facilities, although it is less suitable for examinations that require physical contact. I believe the advantages outweigh the drawbacks when remote appointments are used for appropriate cases and patients can still access in-person care when needed.', vi: 'Khám bệnh qua video cho phép bệnh nhân trao đổi với nhân viên y tế mà không cần đến cơ sở khám chữa bệnh. Cách này có thể tiết kiệm thời gian và đưa tư vấn đến người ở xa cơ sở y tế, dù không phù hợp với việc thăm khám cần tiếp xúc trực tiếp. Tôi cho rằng lợi ích lớn hơn hạn chế khi khám từ xa được dùng cho trường hợp phù hợp và bệnh nhân vẫn tiếp cận được dịch vụ trực tiếp khi cần.', focusVi: 'Mở bài giới thiệu hình thức, nêu hạn chế chính và xác định điều kiện sử dụng.' },
      { en: 'A remote appointment may spare patients a long journey, time away from work and the difficulty of arranging childcare. This is particularly useful for routine follow-ups, discussion of test results and advice about managing a stable condition. People with limited mobility or those in small communities can reach specialists who are not locally available. Clinicians can also use short digital check-ins to monitor progress, potentially identifying a problem before it develops into an urgent visit.', vi: 'Một buổi khám từ xa có thể giúp bệnh nhân tránh chuyến đi dài, nghỉ làm và khó khăn trong việc sắp xếp người trông trẻ. Hình thức này đặc biệt hữu ích cho tái khám định kỳ, trao đổi kết quả xét nghiệm và tư vấn kiểm soát bệnh ổn định. Người hạn chế khả năng di chuyển hoặc sống ở cộng đồng nhỏ có thể tiếp cận chuyên gia không có tại địa phương. Nhân viên y tế cũng có thể dùng các buổi kiểm tra nhanh trực tuyến để theo dõi tiến triển, có khả năng phát hiện vấn đề trước khi cần khám khẩn cấp.', focusVi: 'Thân bài 1 giải thích lợi ích thực tế đối với thời gian, khả năng tiếp cận và theo dõi.' },
      { en: 'The limitation is that a camera cannot replace every diagnostic tool. A clinician may need to examine a wound, listen to the lungs or conduct a test before recommending treatment; poor internet can also interrupt a conversation. There are privacy concerns if sensitive information is discussed on an insecure device. These problems mean that remote care must be carefully triaged, with clear referral routes and confidential platforms. Patients should not be left to decide alone whether a symptom requires urgent physical assessment.', vi: 'Hạn chế là camera không thể thay thế mọi công cụ chẩn đoán. Nhân viên y tế có thể cần kiểm tra vết thương, nghe phổi hoặc làm xét nghiệm trước khi đưa ra điều trị; mạng yếu cũng có thể làm gián đoạn cuộc trao đổi. Quyền riêng tư là mối lo nếu thông tin nhạy cảm được thảo luận trên thiết bị không an toàn. Vì vậy, dịch vụ từ xa cần sàng lọc cẩn thận, có lộ trình chuyển khám rõ ràng và nền tảng bảo mật. Bệnh nhân không nên phải tự quyết định một mình triệu chứng có cần được khám trực tiếp khẩn cấp hay không.', focusVi: 'Thân bài 2 nêu giới hạn chẩn đoán và điều kiện bảo đảm an toàn.' },
      { en: 'Remote consultations are best understood as an additional route into care, not a complete substitute for clinics. They can make routine medical support faster and more equitable, while a hybrid system preserves physical examinations for cases that demand them. With secure technology and effective triage, the convenience and reach of remote appointments outweigh their clinical limitations.', vi: 'Khám từ xa nên được hiểu là một con đường bổ sung để tiếp cận chăm sóc y tế, không phải sự thay thế hoàn toàn cho phòng khám. Hình thức này có thể giúp hỗ trợ y tế thường lệ nhanh chóng và công bằng hơn, trong khi hệ thống kết hợp vẫn dành khám trực tiếp cho trường hợp cần thiết. Với công nghệ an toàn và sàng lọc hiệu quả, sự tiện lợi và phạm vi tiếp cận của khám từ xa lớn hơn những giới hạn lâm sàng.', focusVi: 'Kết luận làm rõ vai trò bổ trợ và khẳng định lợi ích với điều kiện phù hợp.' },
    ],
    vocabulary: [
      { phrase: 'routine follow-ups', meaningVi: 'các buổi tái khám thường lệ', noteVi: 'Cụm chỉ lần khám tiếp theo để theo dõi tiến triển.' },
      { phrase: 'physical assessment', meaningVi: 'đánh giá trực tiếp bằng thăm khám', noteVi: 'Dùng để phân biệt với chẩn đoán từ xa.' },
      { phrase: 'clear referral routes', meaningVi: 'lộ trình chuyển tuyến rõ ràng', noteVi: 'Cụm phù hợp khi nói về tổ chức dịch vụ y tế.' },
    ],
  },
  {
    id: 'sample-t2-extra-advantages-society', topicSlug: 'society', topicEn: 'Society', topicVi: 'Xã hội',
    title: 'Living in multicultural cities',
    promptText: 'Large cities are becoming home to people from a wider range of cultural and national backgrounds. Do the advantages of this change outweigh the disadvantages?',
    paragraphs: [
      { en: 'Many cities now bring together residents with different languages, traditions and personal histories. This diversity can broaden social experience and strengthen economic life, although it may also create communication difficulties or tension over shared values. On balance, I believe the benefits outweigh the challenges when public institutions promote equal participation and neighbourhoods provide opportunities for people to meet.', vi: 'Nhiều thành phố hiện quy tụ cư dân có ngôn ngữ, truyền thống và câu chuyện cá nhân khác nhau. Sự đa dạng này có thể mở rộng trải nghiệm xã hội và củng cố đời sống kinh tế, dù cũng có thể gây khó khăn giao tiếp hoặc căng thẳng về giá trị chung. Nhìn chung, tôi cho rằng lợi ích lớn hơn thách thức nếu các cơ quan công thúc đẩy sự tham gia bình đẳng và khu dân cư tạo cơ hội để mọi người gặp gỡ.', focusVi: 'Mở bài giới thiệu sự đa dạng đô thị, công nhận thách thức và nêu lập trường.' },
      { en: 'Contact with different communities can make residents more open to unfamiliar customs and ways of thinking. Schools, workplaces and local associations may benefit from varied experiences, which can improve problem-solving and encourage new forms of cooperation. Diversity also supports a richer cultural and commercial scene: restaurants, festivals and specialist businesses can attract visitors and serve a wider range of needs. For newcomers, established communities can provide language practice, practical knowledge and social ties that make settling in less isolating.', vi: 'Tiếp xúc với các cộng đồng khác nhau có thể giúp cư dân cởi mở hơn với phong tục và cách suy nghĩ xa lạ. Trường học, nơi làm việc và hội nhóm địa phương có thể hưởng lợi từ trải nghiệm đa dạng, góp phần cải thiện giải quyết vấn đề và khuyến khích cách hợp tác mới. Sự đa dạng cũng làm phong phú đời sống văn hoá và thương mại: nhà hàng, lễ hội và doanh nghiệp chuyên biệt có thể thu hút du khách, đáp ứng nhiều nhu cầu. Với người mới đến, cộng đồng sẵn có có thể giúp luyện ngôn ngữ, chia sẻ kiến thức thực tế và tạo kết nối xã hội để họ bớt cô lập.', focusVi: 'Thân bài 1 mô tả lợi ích văn hoá, kinh tế, xã hội và khả năng hội nhập.' },
      { en: 'Nevertheless, diversity does not automatically produce understanding. Language barriers can make it harder to access public services, and residents may form separate social circles if they rarely share schools, parks or community spaces. Disputes can arise when people interpret religious practices or public behaviour differently. Such problems are worsened by discrimination and unequal access to housing or employment, rather than by cultural variety alone. Translation services, fair rules and shared local activities can address these practical sources of division.', vi: 'Tuy nhiên, đa dạng không tự động tạo ra sự thấu hiểu. Rào cản ngôn ngữ có thể khiến việc tiếp cận dịch vụ công khó hơn, còn cư dân có thể hình thành các vòng xã hội tách biệt nếu hiếm khi dùng chung trường học, công viên hay không gian cộng đồng. Tranh cãi có thể nảy sinh khi mọi người diễn giải khác nhau về thực hành tôn giáo hay hành vi nơi công cộng. Vấn đề trầm trọng hơn do phân biệt đối xử và cơ hội nhà ở, việc làm không bình đẳng, chứ không chỉ vì khác biệt văn hoá. Dịch vụ phiên dịch, quy tắc công bằng và hoạt động địa phương chung có thể xử lý những nguồn chia rẽ thực tế này.', focusVi: 'Thân bài 2 phân tích nguy cơ và phân biệt nguyên nhân xã hội với bản thân sự đa dạng.' },
      { en: 'A multicultural city requires investment in communication and equal access, but those responsibilities are manageable. When residents encounter one another in schools, workplaces and public spaces, difference can become a source of knowledge rather than suspicion. The cultural and social gains are substantial, so the advantages outweigh the disadvantages if inclusion is actively supported.', vi: 'Thành phố đa văn hoá cần đầu tư vào giao tiếp và khả năng tiếp cận bình đẳng, nhưng những trách nhiệm đó có thể quản lý được. Khi cư dân gặp nhau tại trường học, nơi làm việc và không gian công cộng, khác biệt có thể trở thành nguồn tri thức thay vì sự ngờ vực. Lợi ích văn hoá và xã hội là đáng kể, vì vậy ưu điểm lớn hơn bất lợi nếu sự hoà nhập được hỗ trợ chủ động.', focusVi: 'Kết luận tổng hợp lợi ích, đồng thời nhấn mạnh vai trò của chính sách hoà nhập.' },
    ],
    vocabulary: [
      { phrase: 'cultural variety', meaningVi: 'sự đa dạng văn hoá', noteVi: 'Cụm trung tính để bàn về nhiều truyền thống cùng tồn tại.' },
      { phrase: 'equal participation', meaningVi: 'sự tham gia bình đẳng', noteVi: 'Dùng khi nói về cơ hội đóng góp không phân biệt nền tảng.' },
      { phrase: 'language barriers', meaningVi: 'rào cản ngôn ngữ', noteVi: 'Cụm thường dùng để mô tả khó khăn giao tiếp và dịch vụ.' },
    ],
  },
  {
    id: 'sample-t2-extra-advantages-work', topicSlug: 'work', topicEn: 'Work', topicVi: 'Công việc',
    title: 'Working from home',
    promptText: 'More employees are working from home for some or all of the week. Do the advantages of this arrangement outweigh the disadvantages?',
    paragraphs: [
      { en: 'Working from home has shifted from an occasional exception to a regular arrangement in many occupations. It can give employees greater control over their time and reduce commuting, although it can blur boundaries between work and personal life. In my view, the benefits outweigh the drawbacks for many roles, provided employers set realistic expectations and workers have suitable space and support.', vi: 'Làm việc tại nhà đã chuyển từ ngoại lệ thỉnh thoảng thành hình thức thường xuyên trong nhiều ngành nghề. Điều này có thể giúp nhân viên chủ động thời gian hơn và giảm việc đi lại, dù ranh giới giữa công việc với đời sống cá nhân có thể mờ đi. Theo tôi, lợi ích lớn hơn hạn chế với nhiều vị trí, miễn là nhà tuyển dụng đặt kỳ vọng thực tế và người lao động có không gian, hỗ trợ phù hợp.', focusVi: 'Mở bài giới thiệu hình thức, thừa nhận mặt trái và nêu quan điểm có điều kiện.' },
      { en: 'The most immediate gain is the time no longer spent travelling to an office. Employees can use it for rest, family responsibilities or additional work, and people who live far from major employment centres can apply for a wider range of jobs. Flexible schedules may also help caregivers and people with mobility limitations remain in paid employment. Employers can reduce demand for office space, while fewer daily car journeys may ease congestion and transport emissions in large cities.', vi: 'Lợi ích tức thời nhất là thời gian không còn dành cho việc đi đến văn phòng. Nhân viên có thể dùng thời gian đó để nghỉ ngơi, chăm lo gia đình hoặc làm thêm việc; người sống xa trung tâm việc làm có thể ứng tuyển nhiều vị trí hơn. Lịch linh hoạt cũng giúp người chăm sóc gia đình và người hạn chế khả năng di chuyển tiếp tục làm công ăn lương. Nhà tuyển dụng có thể giảm nhu cầu về văn phòng, còn ít chuyến xe đi làm hằng ngày hơn có thể giảm tắc nghẽn và khí thải giao thông ở thành phố lớn.', focusVi: 'Thân bài 1 nêu lợi ích với thời gian, cơ hội việc làm, doanh nghiệp và đô thị.' },
      { en: 'However, home-based staff may miss informal learning and the sense of connection that grows through daily contact. New employees can find it difficult to ask quick questions, and digital meetings may encourage constant availability rather than genuine flexibility. Not everyone has a quiet room, reliable internet or a clear separation from domestic duties. These disadvantages are real, so remote work should include regular team meetings, boundaries around response times and access to shared workspaces when home is unsuitable.', vi: 'Tuy nhiên, nhân viên làm tại nhà có thể bỏ lỡ việc học hỏi không chính thức và cảm giác gắn kết hình thành qua tiếp xúc hằng ngày. Nhân viên mới có thể khó hỏi nhanh, còn họp trực tuyến dễ khiến mọi người luôn phải sẵn sàng thay vì thực sự linh hoạt. Không phải ai cũng có phòng yên tĩnh, mạng ổn định hay ranh giới rõ ràng với việc nhà. Những bất lợi này có thật, vì vậy làm việc từ xa cần có họp nhóm định kỳ, giới hạn thời gian phản hồi và nơi làm việc chung khi nhà không phù hợp.', focusVi: 'Thân bài 2 nêu vấn đề về gắn kết, ranh giới và điều kiện vật chất, kèm biện pháp hỗ trợ.' },
      { en: 'Remote work is not equally suitable for every job or household, but its flexibility can improve access to employment and quality of life. A hybrid approach can preserve team contact while reducing unnecessary commuting. Where tasks can be done effectively at a distance, these gains outweigh the disadvantages if organisations deliberately maintain communication and reasonable working boundaries.', vi: 'Làm việc từ xa không phù hợp như nhau với mọi công việc hay gia đình, nhưng sự linh hoạt có thể cải thiện khả năng tiếp cận việc làm và chất lượng cuộc sống. Mô hình kết hợp có thể duy trì sự gắn kết nhóm trong khi giảm việc đi lại không cần thiết. Với những nhiệm vụ có thể hoàn thành hiệu quả từ xa, lợi ích lớn hơn bất lợi nếu tổ chức chủ động duy trì giao tiếp và ranh giới làm việc hợp lý.', focusVi: 'Kết luận xác định phạm vi phù hợp và bảo vệ mô hình kết hợp.' },
    ],
    vocabulary: [
      { phrase: 'employment centres', meaningVi: 'các trung tâm việc làm', noteVi: 'Cụm chỉ khu vực tập trung nhiều cơ hội nghề nghiệp.' },
      { phrase: 'constant availability', meaningVi: 'tình trạng luôn phải sẵn sàng', noteVi: 'Dùng khi mô tả ranh giới công việc bị xoá nhoà.' },
      { phrase: 'hybrid approach', meaningVi: 'cách tiếp cận kết hợp', noteVi: 'Ở đây chỉ sự phối hợp giữa làm tại nhà và văn phòng.' },
    ],
  },
  {
    id: 'sample-t2-extra-advantages-transport', topicSlug: 'transport', topicEn: 'Transport', topicVi: 'Giao thông',
    title: 'High-speed rail networks',
    promptText: 'Governments are spending large sums on high-speed rail links between major cities. Do the advantages of this investment outweigh its disadvantages?',
    paragraphs: [
      { en: 'High-speed rail can connect major cities in a fraction of the time required by conventional trains. Building such networks is expensive and may disrupt communities along the route, but it can offer a lower-emission alternative to domestic flights and encourage regional growth. I believe its advantages outweigh the costs where passenger demand is strong and projects are integrated with local transport.', vi: 'Đường sắt tốc độ cao có thể kết nối các thành phố lớn trong thời gian chỉ bằng một phần so với tàu thông thường. Xây dựng mạng lưới như vậy tốn kém và có thể ảnh hưởng cộng đồng dọc tuyến, nhưng có thể tạo lựa chọn ít phát thải hơn các chuyến bay nội địa và thúc đẩy tăng trưởng vùng. Tôi cho rằng lợi ích lớn hơn chi phí ở nơi có nhu cầu đi lại cao và dự án được kết nối với giao thông địa phương.', focusVi: 'Mở bài giới thiệu lợi ích, chi phí và điều kiện để khoản đầu tư có giá trị.' },
      { en: 'A fast rail service makes same-day travel between distant urban centres more practical for work, study and family visits. It can also take passengers off crowded roads and short-haul flights, reducing pressure on airports and potentially lowering transport emissions per traveller. Stations often attract offices, housing and services, so places beyond the largest capitals may gain investment and jobs. If ticket prices are accessible, these links can expand people’s choices without requiring them to own a car or fly.', vi: 'Dịch vụ tàu nhanh khiến việc đi lại trong ngày giữa các đô thị xa nhau trở nên thiết thực hơn cho công việc, học tập và thăm gia đình. Tàu cũng có thể đưa hành khách khỏi đường đông và chuyến bay ngắn, giảm áp lực lên sân bay và có thể hạ phát thải giao thông tính trên mỗi người. Ga tàu thường thu hút văn phòng, nhà ở và dịch vụ, nên các khu vực ngoài thủ đô lớn nhất có thể có thêm đầu tư và việc làm. Nếu giá vé phù hợp, tuyến tàu mở rộng lựa chọn mà không cần sở hữu ô tô hay đi máy bay.', focusVi: 'Thân bài 1 trình bày lợi ích về kết nối, môi trường và phát triển kinh tế vùng.' },
      { en: 'These projects demand substantial public funds, and construction can require land acquisition, noise controls and changes to established neighbourhoods. Benefits may also be concentrated among people living near stations, while smaller towns on the route receive little service. If ridership forecasts are too optimistic, taxpayers may bear the cost of underused infrastructure. Careful demand studies, transparent budgeting and compensation for affected residents can reduce these risks, while feeder buses and local rail ensure that access is not limited to city-centre passengers.', vi: 'Những dự án này đòi hỏi ngân sách công lớn, còn quá trình thi công có thể cần thu hồi đất, kiểm soát tiếng ồn và thay đổi khu dân cư hiện hữu. Lợi ích cũng có thể tập trung vào người sống gần ga, trong khi thị trấn nhỏ dọc tuyến được phục vụ ít. Nếu dự báo lượng khách quá lạc quan, người đóng thuế có thể phải gánh chi phí cho hạ tầng ít sử dụng. Nghiên cứu nhu cầu cẩn trọng, ngân sách minh bạch và bồi thường cho cư dân bị ảnh hưởng có thể giảm rủi ro; xe buýt trung chuyển và đường sắt địa phương giúp nhiều người tiếp cận hơn.', focusVi: 'Thân bài 2 phân tích chi phí, tác động cộng đồng và nguy cơ phân bổ lợi ích không đều.' },
      { en: 'High-speed rail is worthwhile when it responds to genuine travel demand and complements a wider public transport network. Its initial expense is considerable, but reduced road and air pressure, faster journeys and wider regional access can provide lasting returns. Governments should select routes carefully and include smaller communities in transport planning so that public investment produces broad benefits.', vi: 'Đường sắt tốc độ cao đáng đầu tư khi đáp ứng nhu cầu đi lại thực tế và bổ sung cho mạng lưới giao thông công cộng rộng hơn. Chi phí ban đầu rất lớn, nhưng việc giảm áp lực đường bộ, hàng không, rút ngắn hành trình và mở rộng tiếp cận vùng có thể đem lại lợi ích dài hạn. Chính phủ nên lựa chọn tuyến cẩn trọng và đưa cộng đồng nhỏ hơn vào quy hoạch giao thông để đầu tư công tạo lợi ích rộng khắp.', focusVi: 'Kết luận đặt điều kiện hiệu quả và khẳng định lợi ích dài hạn.' },
    ],
    vocabulary: [
      { phrase: 'short-haul flights', meaningVi: 'các chuyến bay chặng ngắn', noteVi: 'Cụm thường dùng khi so sánh tàu với hàng không nội địa.' },
      { phrase: 'ridership forecasts', meaningVi: 'dự báo lượng hành khách', noteVi: 'Dùng trong đánh giá hiệu quả đầu tư giao thông.' },
      { phrase: 'feeder buses', meaningVi: 'xe buýt trung chuyển', noteVi: 'Phương tiện đưa khách từ khu vực lân cận đến ga chính.' },
    ],
  },
  {
    id: 'sample-t2-extra-advantages-media', topicSlug: 'media', topicEn: 'Media', topicVi: 'Truyền thông',
    title: 'Getting news through social media',
    promptText: 'A growing number of people get news through social media platforms rather than traditional newspapers or broadcasters. Do the advantages of this trend outweigh the disadvantages?',
    paragraphs: [
      { en: 'Social media has become a common news source, often before people visit a newspaper or broadcaster. It gives stories a wide and rapid reach, but the same speed can spread inaccurate material and personal recommendations may narrow what users see. I believe the benefits are greater only when platforms and readers take responsibility for checking sources and distinguishing reporting from opinion.', vi: 'Mạng xã hội đã trở thành kênh chính để nhiều người tiếp cận tin tức, thường là trước khi họ đọc báo hay xem đài. Nó giúp tin tức lan truyền nhanh và rộng, nhưng tốc độ ấy cũng có thể phát tán nội dung sai lệch, còn gợi ý cá nhân hoá có thể thu hẹp những gì người dùng nhìn thấy. Tôi cho rằng lợi ích lớn hơn chỉ khi nền tảng và độc giả có trách nhiệm kiểm tra nguồn, phân biệt tin đưa với ý kiến.', focusVi: 'Mở bài nêu tốc độ tiếp cận, mặt trái và điều kiện để xu hướng có lợi.' },
      { en: 'A post can reach people within seconds, including those who do not subscribe to a newspaper or follow a television schedule. Users can also receive updates during emergencies and see accounts from witnesses at the scene, while links make it easy to compare coverage from several outlets. For smaller organisations, social platforms provide a relatively inexpensive way to reach an audience. This wider access can bring neglected local events into public discussion and help people respond quickly to developing situations.', vi: 'Một bài đăng có thể tiếp cận mọi người trong vài giây, kể cả người không đặt mua báo hay theo dõi lịch phát sóng truyền hình. Người dùng cũng có thể nhận tin cập nhật khi khẩn cấp và xem lời kể từ nhân chứng tại hiện trường, còn đường dẫn giúp so sánh đưa tin của nhiều cơ quan. Với tổ chức nhỏ, nền tảng xã hội là cách tiếp cận khán giả tương đối ít tốn kém. Khả năng tiếp cận rộng hơn có thể đưa sự kiện địa phương ít được chú ý vào thảo luận công khai và giúp mọi người ứng phó nhanh với tình hình mới.', focusVi: 'Thân bài 1 giải thích tính nhanh, rộng, tương tác và cơ hội cho nguồn tin nhỏ.' },
      { en: 'The weakness is that popularity is not a reliable measure of accuracy. A misleading claim may be shared widely before it is corrected, and emotional content can attract more attention than careful reporting. Algorithms may repeatedly show users material similar to what they already engage with, leaving them less exposed to different views. In addition, people may mistake an unverified witness post for professional journalism. Media literacy, transparent corrections and clear labels can help, although readers still need to pause and check where a claim originated.', vi: 'Điểm yếu là mức độ phổ biến không phải thước đo đáng tin cậy về độ chính xác. Một nhận định sai có thể được chia sẻ rộng trước khi đính chính, còn nội dung gây xúc động thường thu hút chú ý hơn tin bài cẩn trọng. Thuật toán có thể liên tục hiển thị nội dung giống thứ người dùng vốn quan tâm, khiến họ ít tiếp xúc với quan điểm khác. Ngoài ra, người đọc có thể nhầm bài đăng chưa kiểm chứng của nhân chứng với báo chí chuyên nghiệp. Giáo dục truyền thông, đính chính minh bạch và nhãn rõ ràng có thể hỗ trợ, dù độc giả vẫn cần dừng lại để xác minh nguồn gốc thông tin.', focusVi: 'Thân bài 2 nêu rủi ro về sai lệch, buồng thông tin và nhầm lẫn nguồn tin.' },
      { en: 'Social platforms make news more immediate and accessible, a valuable change in an emergency or for communities overlooked by large outlets. However, that advantage depends on users treating online posts critically and platforms making credible reporting easy to identify. With these safeguards, social media can broaden news access more than it undermines it, while traditional journalism remains essential for verification and accountability.', vi: 'Nền tảng xã hội giúp tin tức tức thời và dễ tiếp cận hơn, một thay đổi có giá trị khi khẩn cấp hoặc với cộng đồng ít được truyền thông lớn chú ý. Tuy nhiên, lợi ích phụ thuộc vào việc người dùng tiếp nhận bài đăng trực tuyến một cách phản biện và nền tảng giúp nhận diện tin đáng tin cậy. Với những biện pháp bảo vệ này, mạng xã hội có thể mở rộng tiếp cận tin tức nhiều hơn là làm suy yếu nó, trong khi báo chí truyền thống vẫn cần thiết cho kiểm chứng và trách nhiệm giải trình.', focusVi: 'Kết luận cân đối vai trò mới của nền tảng với chức năng báo chí chuyên nghiệp.' },
    ],
    vocabulary: [
      { phrase: 'witness accounts', meaningVi: 'lời kể của nhân chứng', noteVi: 'Cụm dùng cho thông tin do người chứng kiến cung cấp.' },
      { phrase: 'media literacy', meaningVi: 'năng lực hiểu biết truyền thông', noteVi: 'Khả năng đánh giá, xác minh và diễn giải nội dung truyền thông.' },
      { phrase: 'professional journalism', meaningVi: 'báo chí chuyên nghiệp', noteVi: 'Phân biệt hoạt động đưa tin có quy trình với bài đăng cá nhân.' },
    ],
  },
  {
    id: 'sample-t2-extra-advantages-crime', topicSlug: 'crime', topicEn: 'Crime', topicVi: 'Tội phạm',
    title: 'CCTV in public places',
    promptText: 'Authorities are installing more CCTV cameras in streets, stations and other public places to prevent crime. Do the advantages of this policy outweigh the disadvantages?',
    paragraphs: [
      { en: 'Cameras are now a familiar feature of transport hubs, shopping areas and city streets. They may deter some offences and help investigators reconstruct events, but constant recording raises concerns about privacy and the use of stored footage. On balance, I believe carefully regulated CCTV can improve public safety, although it should support rather than replace effective policing and community services.', vi: 'Camera hiện đã quen thuộc tại đầu mối giao thông, khu mua sắm và đường phố. Chúng có thể ngăn một số hành vi phạm pháp và giúp điều tra viên dựng lại sự việc, nhưng việc ghi hình liên tục làm dấy lên lo ngại về quyền riêng tư và việc sử dụng dữ liệu lưu trữ. Nhìn chung, tôi cho rằng camera được quản lý cẩn trọng có thể cải thiện an toàn công cộng, dù nên hỗ trợ chứ không thay thế hoạt động cảnh sát và dịch vụ cộng đồng hiệu quả.', focusVi: 'Mở bài nêu công dụng, lo ngại về quyền riêng tư và lập trường có điều kiện.' },
      { en: 'Visible cameras can make offenders think twice about stealing or damaging property, especially in places where a quick escape would otherwise be easy. When a crime does occur, recordings may help establish a sequence of events, identify a suspect or confirm an account given by a victim. This evidence can guide an investigation and may help protect someone who has been wrongly accused. Cameras are also useful for monitoring crowded stations, where staff can notice an emergency and direct assistance to the right area.', vi: 'Camera dễ nhìn thấy có thể khiến người định trộm cắp hay phá hoại tài sản phải cân nhắc, nhất là ở nơi họ có thể dễ dàng tẩu thoát. Khi tội phạm xảy ra, đoạn ghi hình có thể giúp xác lập trình tự sự kiện, nhận diện nghi phạm hoặc xác nhận lời trình bày của nạn nhân. Bằng chứng này có thể định hướng điều tra và bảo vệ người bị buộc tội oan. Camera cũng hữu ích để giám sát ga đông người, nơi nhân viên có thể phát hiện tình huống khẩn cấp và điều phối hỗ trợ đúng khu vực.', focusVi: 'Thân bài 1 phát triển các lợi ích về răn đe, điều tra và phản ứng khẩn cấp.' },
      { en: 'Recording everyone in public can make ordinary residents feel that they are treated as suspects. Footage may reveal sensitive information about people’s movements, and poor security or excessive retention could expose it to misuse. Cameras can also create a false sense of safety if officials invest in equipment while neglecting lighting, youth services or investigation staff. Clear limits on access, short retention periods, independent oversight and published rules are therefore essential. Authorities should target places with documented problems instead of monitoring entire communities without justification.', vi: 'Ghi hình tất cả mọi người nơi công cộng có thể khiến cư dân bình thường cảm thấy mình bị xem như nghi phạm. Video có thể tiết lộ thông tin nhạy cảm về việc đi lại, còn bảo mật yếu hoặc lưu quá lâu có thể khiến dữ liệu bị lạm dụng. Camera cũng có thể tạo cảm giác an toàn giả nếu cơ quan chức năng đầu tư thiết bị nhưng bỏ bê chiếu sáng, dịch vụ thanh thiếu niên hoặc nhân lực điều tra. Vì vậy, cần quy định rõ quyền truy cập, thời hạn lưu ngắn, giám sát độc lập và công bố quy tắc. Chính quyền nên tập trung vào nơi có vấn đề được ghi nhận thay vì theo dõi cả cộng đồng mà không có căn cứ.', focusVi: 'Thân bài 2 nêu nguy cơ xâm phạm riêng tư và thay thế sai lệch các giải pháp phòng ngừa.' },
      { en: 'CCTV can be a useful element of public safety when its purpose is limited and its use is accountable. The evidence it provides and the deterrence it may create outweigh the privacy cost in carefully chosen locations, but blanket surveillance would not be justified. Combining cameras with other prevention measures and strict data rules offers a more proportionate response to crime.', vi: 'Camera giám sát có thể là một thành tố hữu ích của an toàn công cộng khi mục đích giới hạn và việc sử dụng có trách nhiệm giải trình. Bằng chứng mà nó cung cấp cùng tác dụng răn đe có thể lớn hơn chi phí về riêng tư tại những địa điểm được chọn kỹ, nhưng giám sát tràn lan là không chính đáng. Kết hợp camera với biện pháp phòng ngừa khác và quy định dữ liệu nghiêm ngặt là cách ứng phó tội phạm cân xứng hơn.', focusVi: 'Kết luận khẳng định giá trị trong phạm vi phù hợp và bác bỏ giám sát không giới hạn.' },
    ],
    vocabulary: [
      { phrase: 'deter offences', meaningVi: 'ngăn chặn hành vi phạm pháp', noteVi: 'Động từ deter nhấn vào tác dụng khiến người ta không thực hiện việc sai trái.' },
      { phrase: 'retention periods', meaningVi: 'thời hạn lưu trữ', noteVi: 'Cụm phù hợp khi bàn về thời gian dữ liệu được giữ lại.' },
      { phrase: 'independent oversight', meaningVi: 'sự giám sát độc lập', noteVi: 'Dùng khi đề xuất kiểm soát từ cơ quan không trực tiếp vận hành.' },
    ],
  },
  {
    id: 'sample-t2-extra-advantages-government', topicSlug: 'government', topicEn: 'Government', topicVi: 'Chính phủ',
    title: 'Hosting international sporting events',
    promptText: 'Governments sometimes spend heavily to host international sporting events such as world championships. Do the advantages of hosting these events outweigh the disadvantages?',
    paragraphs: [
      { en: 'Hosting a major international sporting event can place a city in the global spotlight and bring visitors for a short period. The preparations require public money and can leave costly facilities behind, so the decision is not automatically worthwhile. I believe the benefits outweigh the risks only when budgets are transparent and venues have a credible use after the event ends.', vi: 'Tổ chức sự kiện thể thao quốc tế lớn có thể đưa một thành phố ra trước sự chú ý toàn cầu và thu hút du khách trong thời gian ngắn. Công tác chuẩn bị cần tiền công và có thể để lại cơ sở vật chất tốn kém, nên quyết định này không đương nhiên đáng giá. Tôi cho rằng lợi ích lớn hơn rủi ro chỉ khi ngân sách minh bạch và địa điểm có phương án sử dụng khả thi sau khi sự kiện kết thúc.', focusVi: 'Mở bài nêu sức hút, chi phí và điều kiện để sự kiện mang lại lợi ích.' },
      { en: 'A tournament can generate temporary demand for hotels, restaurants, transport and local services. It may also encourage governments to improve stations, roads or public spaces that residents continue to use afterwards. International broadcasts provide publicity that would be expensive to purchase directly, helping a city attract future tourists or conferences. For local people, the event can create shared excitement and volunteer opportunities, while a successful programme may strengthen confidence in the city’s ability to organise complex projects.', vi: 'Một giải đấu có thể tạo nhu cầu tạm thời cho khách sạn, nhà hàng, giao thông và dịch vụ địa phương. Nó cũng có thể thúc đẩy chính phủ cải thiện ga tàu, đường sá hoặc không gian công cộng để cư dân tiếp tục sử dụng. Phát sóng quốc tế tạo độ quảng bá mà nếu mua trực tiếp sẽ rất tốn kém, giúp thành phố thu hút du khách hoặc hội nghị sau này. Với người dân địa phương, sự kiện có thể tạo không khí phấn khởi và cơ hội tình nguyện; chương trình thành công còn củng cố niềm tin vào năng lực tổ chức dự án phức tạp của thành phố.', focusVi: 'Thân bài 1 nêu lợi ích kinh tế ngắn hạn, hạ tầng, quảng bá và gắn kết.' },
      { en: 'The danger is that officials may promise lasting growth while spending far beyond the original budget. New stadiums can become underused once spectators leave, and public funds may be diverted from schools, hospitals or daily transport. Construction can displace residents or disrupt businesses, while benefits often go to developers and visitors more than to low-income communities. Independent cost reviews, limits on public guarantees and a plan to convert venues for everyday use can reduce these risks, but they cannot make a poor project sensible.', vi: 'Nguy cơ là quan chức có thể hứa hẹn tăng trưởng lâu dài trong khi chi tiêu vượt xa ngân sách ban đầu. Sân vận động mới có thể ít được sử dụng sau khi khán giả rời đi, còn tiền công có thể bị rút khỏi trường học, bệnh viện hay giao thông thường ngày. Xây dựng có thể khiến cư dân phải di dời hoặc làm gián đoạn doanh nghiệp, trong khi lợi ích thường đến với nhà phát triển và khách tham quan nhiều hơn cộng đồng thu nhập thấp. Đánh giá chi phí độc lập, giới hạn bảo lãnh công và kế hoạch chuyển đổi địa điểm cho sử dụng thường nhật có thể giảm rủi ro, nhưng không thể biến dự án kém thành hợp lý.', focusVi: 'Thân bài 2 phân tích vượt ngân sách, chi phí cơ hội và phân phối lợi ích bất bình đẳng.' },
      { en: 'An international event can be a worthwhile public investment, but only if its legacy is planned before construction begins. Reusable venues, open accounting and benefits that reach residents make the case stronger than prestige alone. Under these conditions, visitor spending and lasting improvements can outweigh the financial and social costs; without them, a city risks paying heavily for a brief spectacle.', vi: 'Sự kiện quốc tế có thể là khoản đầu tư công đáng giá, nhưng chỉ khi di sản được hoạch định trước khi khởi công. Địa điểm có thể tái sử dụng, kế toán công khai và lợi ích đến được với cư dân tạo cơ sở thuyết phục hơn danh tiếng đơn thuần. Với những điều kiện này, chi tiêu của khách và cải thiện dài hạn có thể lớn hơn chi phí tài chính, xã hội; nếu không, thành phố có nguy cơ trả giá đắt cho một màn trình diễn chóng tàn.', focusVi: 'Kết luận đưa ra phép thử về tính lâu dài và chốt quan điểm có điều kiện.' },
    ],
    vocabulary: [
      { phrase: 'public funds', meaningVi: 'ngân quỹ công', noteVi: 'Cụm dùng cho tiền ngân sách do nhà nước quản lý.' },
      { phrase: 'cost reviews', meaningVi: 'đánh giá chi phí', noteVi: 'Cụm chỉ việc thẩm định độc lập các khoản dự kiến và thực tế.' },
      { phrase: 'lasting improvements', meaningVi: 'những cải thiện lâu dài', noteVi: 'Dùng để đánh giá di sản sau một dự án hoặc sự kiện.' },
    ],
  },
  {
    id: 'sample-t2-extra-advantages-culture', topicSlug: 'culture', topicEn: 'Culture', topicVi: 'Văn hoá',
    title: 'Using a shared international language',
    promptText: 'In many countries, people are learning and using the same international language for study and work. Do the advantages of this trend outweigh the disadvantages?',
    paragraphs: [
      { en: 'A shared international language makes it easier for people from different countries to communicate in education, business and travel. Its growing use can improve cooperation, but it may also put pressure on local languages and the cultural knowledge they carry. Overall, I believe the practical advantages are greater if schools and public institutions also protect opportunities to learn and use community languages.', vi: 'Một ngôn ngữ quốc tế chung giúp người ở các quốc gia khác nhau giao tiếp dễ dàng hơn trong giáo dục, kinh doanh và du lịch. Việc sử dụng ngày càng rộng có thể cải thiện hợp tác, nhưng cũng có thể gây áp lực lên ngôn ngữ địa phương và tri thức văn hoá mà ngôn ngữ lưu giữ. Nhìn chung, tôi cho rằng lợi ích thực tiễn lớn hơn nếu trường học và cơ quan công cũng bảo vệ cơ hội học và sử dụng tiếng nói cộng đồng.', focusVi: 'Mở bài nêu lợi thế giao tiếp, nguy cơ đối với ngôn ngữ địa phương và điều kiện bảo tồn.' },
      { en: 'A common language lowers the effort needed to exchange ideas across borders. Students can use a larger pool of academic material, and researchers can share findings without translating every paper into multiple languages. Employers may recruit internationally, while workers can pursue jobs or training beyond their home region. Visitors also find it easier to ask for help and take part in local life. These shared means of communication do not remove cultural differences, but they allow people to discuss them directly.', vi: 'Ngôn ngữ chung giảm công sức cần thiết để trao đổi ý tưởng xuyên biên giới. Sinh viên có thể dùng kho tài liệu học thuật rộng hơn, còn nhà nghiên cứu chia sẻ phát hiện mà không phải dịch mọi bài báo sang nhiều thứ tiếng. Nhà tuyển dụng có thể tuyển nhân sự quốc tế, trong khi người lao động có thể tìm việc hoặc học nghề ngoài khu vực quê nhà. Du khách cũng dễ hỏi thông tin và tham gia đời sống địa phương hơn. Phương tiện giao tiếp chung không xoá bỏ khác biệt văn hoá, nhưng giúp mọi người trao đổi trực tiếp về chúng.', focusVi: 'Thân bài 1 phát triển lợi ích học thuật, nghề nghiệp và giao tiếp xuyên biên giới.' },
      { en: 'The concern is that people may come to see smaller languages as less useful or prestigious. If families stop passing them to children, oral histories, local expressions and ways of describing the natural world can disappear with them. Learners may also face unequal pressure when access to good language instruction is limited to wealthier schools. These effects are not an unavoidable result of having a shared language: education systems can teach it alongside local languages, fund community programmes and include local literature in the curriculum.', vi: 'Mối lo là mọi người có thể xem các ngôn ngữ nhỏ hơn là kém hữu dụng hoặc ít danh giá. Nếu gia đình ngừng truyền tiếng mẹ đẻ cho trẻ, lịch sử truyền miệng, cách diễn đạt địa phương và cách mô tả thế giới tự nhiên có thể biến mất theo. Người học cũng có thể chịu áp lực bất bình đẳng khi việc học ngôn ngữ tốt chỉ dành cho trường giàu. Những tác động này không phải hệ quả tất yếu của việc có một ngôn ngữ chung: hệ thống giáo dục có thể dạy ngôn ngữ đó cùng tiếng địa phương, tài trợ chương trình cộng đồng và đưa văn học bản địa vào chương trình.', focusVi: 'Thân bài 2 nêu rủi ro mai một văn hoá và bất bình đẳng, rồi chỉ ra giải pháp song ngữ.' },
      { en: 'A shared language can open valuable channels for knowledge, work and human contact. Those gains should not require communities to abandon their own means of expression. When international communication is taught as an addition to local languages, rather than a replacement for them, its practical advantages clearly outweigh the cultural risks.', vi: 'Ngôn ngữ chung có thể mở ra những kênh quý giá cho tri thức, công việc và giao tiếp giữa con người. Những lợi ích ấy không nên đòi hỏi cộng đồng từ bỏ cách biểu đạt của mình. Khi giao tiếp quốc tế được dạy như phần bổ sung cho ngôn ngữ địa phương thay vì vật thay thế, ưu điểm thực tiễn rõ ràng lớn hơn rủi ro văn hoá.', focusVi: 'Kết luận chốt điều kiện bổ sung thay vì thay thế để dung hoà hai phía.' },
    ],
    vocabulary: [
      { phrase: 'exchange ideas', meaningVi: 'trao đổi ý tưởng', noteVi: 'Cụm động từ thông dụng trong bối cảnh học tập và hợp tác.' },
      { phrase: 'oral histories', meaningVi: 'lịch sử truyền miệng', noteVi: 'Tri thức lịch sử được lưu truyền qua lời kể.' },
      { phrase: 'community languages', meaningVi: 'ngôn ngữ của cộng đồng', noteVi: 'Chỉ các ngôn ngữ được sử dụng trong cộng đồng địa phương.' },
    ],
  },
  {
    id: 'sample-t2-extra-advantages-tourism', topicSlug: 'tourism', topicEn: 'Tourism', topicVi: 'Du lịch',
    title: 'Growth in international tourism',
    promptText: 'International tourism has expanded rapidly, bringing larger numbers of visitors to many destinations. Do the advantages of this growth outweigh the disadvantages?',
    paragraphs: [
      { en: 'International travel lets more people visit distant places, and tourism now supports many local economies. A larger visitor population can create jobs and cultural exchange, but it can also strain housing, public spaces and natural sites. I believe the advantages outweigh the costs when destinations manage visitor numbers and direct some of the revenue towards residents and conservation.', vi: 'Du lịch quốc tế giúp nhiều người có thể đến những nơi xa nhà, và ngành này hiện hỗ trợ nhiều nền kinh tế địa phương. Lượng du khách đông hơn có thể tạo việc làm và giao lưu văn hoá, nhưng cũng gây áp lực lên nhà ở, không gian công cộng và địa điểm tự nhiên. Tôi cho rằng lợi ích lớn hơn chi phí khi điểm đến quản lý số khách và dành một phần doanh thu cho cư dân, bảo tồn.', focusVi: 'Mở bài nêu quy mô xu hướng, hai mặt tác động và điều kiện quản lý.' },
      { en: 'Visitors spend money on accommodation, food, transport, guides and locally made goods. This demand supports employment beyond large hotels, including family-run cafés and cultural organisations. Tourism can also encourage investment in roads, sanitation and public spaces that residents use throughout the year. Contact between visitors and hosts may create interest in local history, crafts and food, giving communities an economic reason to maintain traditions. In places with few other industries, these opportunities can provide households with an important source of income.', vi: 'Du khách chi tiền cho chỗ ở, thực phẩm, giao thông, hướng dẫn viên và hàng hoá địa phương. Nhu cầu này hỗ trợ việc làm ngoài các khách sạn lớn, bao gồm quán ăn gia đình và tổ chức văn hoá. Du lịch cũng có thể thúc đẩy đầu tư vào đường sá, vệ sinh và không gian công cộng mà cư dân sử dụng quanh năm. Tiếp xúc giữa khách và chủ nhà có thể khơi gợi sự quan tâm đến lịch sử, nghề thủ công và ẩm thực địa phương, tạo động lực kinh tế để gìn giữ truyền thống. Ở nơi có ít ngành khác, cơ hội này đem lại nguồn thu quan trọng cho hộ gia đình.', focusVi: 'Thân bài 1 giải thích tác động đến việc làm, dịch vụ và gìn giữ di sản.' },
      { en: 'Rapid growth can make destinations less pleasant for the people who live there. Short-term rentals may reduce the supply of long-term homes, while crowded streets and higher prices affect daily routines. Sensitive ecosystems can be damaged by waste, traffic and visitors who leave marked paths. Local culture may also be simplified into performances designed only for tourists. These pressures are not solved by promotion alone; visitor limits in fragile areas, housing rules and a fair tourism levy can help communities share in decisions and benefits.', vi: 'Tăng trưởng quá nhanh có thể khiến điểm đến kém dễ chịu với người dân sống tại đó. Chỗ ở ngắn hạn có thể làm giảm nguồn nhà cho thuê dài hạn, còn đường phố đông và giá cả cao ảnh hưởng sinh hoạt thường ngày. Hệ sinh thái nhạy cảm có thể bị hư hại bởi rác thải, giao thông và du khách rời khỏi đường mòn. Văn hoá địa phương cũng có thể bị đơn giản hoá thành tiết mục chỉ phục vụ khách. Quảng bá không tự giải quyết được áp lực này; giới hạn khách ở khu vực mong manh, quy định nhà ở và phí du lịch công bằng có thể giúp cộng đồng cùng quyết định và hưởng lợi.', focusVi: 'Thân bài 2 chỉ ra chi phí cho cư dân và môi trường, đồng thời đưa giải pháp quản lý.' },
      { en: 'Tourism can bring valuable income and create a reason to maintain local heritage, but unmanaged growth risks damaging the very places people come to see. With visitor controls and local investment, the economic gains are substantial and can outweigh the disadvantages. The success of tourism should therefore be measured by benefits to residents as well as the number of arrivals.', vi: 'Du lịch có thể đem lại thu nhập quý giá và tạo lý do gìn giữ di sản địa phương, nhưng tăng trưởng không kiểm soát có nguy cơ phá hỏng chính những nơi thu hút du khách. Với giới hạn khách và đầu tư địa phương, lợi ích kinh tế đáng kể và có thể lớn hơn bất lợi. Vì vậy, thành công du lịch cần được đo bằng lợi ích cho cư dân chứ không chỉ số lượt khách đến.', focusVi: 'Kết luận khẳng định lợi ích khi được quản lý và đề xuất thước đo thành công.' },
    ],
    vocabulary: [
      { phrase: 'family-run cafés', meaningVi: 'quán cà phê do gia đình điều hành', noteVi: 'Cụm cụ thể hoá doanh nghiệp nhỏ địa phương.' },
      { phrase: 'sensitive ecosystems', meaningVi: 'hệ sinh thái nhạy cảm', noteVi: 'Chỉ môi trường tự nhiên dễ bị tổn hại.' },
      { phrase: 'visitor limits', meaningVi: 'giới hạn số lượng khách', noteVi: 'Biện pháp kiểm soát lượng người tại điểm đến.' },
    ],
  },
  {
    id: 'sample-t2-extra-advantages-science', topicSlug: 'science', topicEn: 'Science', topicVi: 'Khoa học',
    title: 'Investment in space exploration',
    promptText: 'Governments and private companies are investing increasing amounts in space exploration. Do the advantages of this investment outweigh the disadvantages?',
    paragraphs: [
      { en: 'Space exploration attracts substantial public and private investment, from satellite missions to research beyond Earth. It can deepen scientific understanding and generate useful technologies, yet it competes for money with needs closer to home and involves uncertain outcomes. I believe the benefits outweigh the disadvantages when programmes are transparent, peaceful and balanced with essential services on Earth.', vi: 'Khám phá không gian thu hút khoản đầu tư lớn từ khu vực công và tư, từ sứ mệnh vệ tinh đến nghiên cứu bên ngoài Trái Đất. Hoạt động này có thể mở rộng hiểu biết khoa học và tạo công nghệ hữu ích, nhưng cạnh tranh ngân sách với nhu cầu gần gũi hơn và có kết quả không chắc chắn. Tôi cho rằng lợi ích lớn hơn bất lợi khi chương trình minh bạch, hoà bình và cân bằng với dịch vụ thiết yếu trên Trái Đất.', focusVi: 'Mở bài giới thiệu đầu tư, lợi ích tiềm năng, chi phí cơ hội và lập trường có điều kiện.' },
      { en: 'Research in space has improved knowledge of planets, climate and the conditions that support life. Satellites developed for scientific missions also help forecast storms, map fires and maintain communication across remote regions. Engineering challenges can lead to advances in materials, sensors and energy systems that later find uses in medicine or industry. The search for life beyond Earth may also encourage international cooperation and give young people a vivid reason to study physics, computing and mathematics.', vi: 'Nghiên cứu trong không gian cải thiện hiểu biết về các hành tinh, khí hậu và điều kiện duy trì sự sống. Vệ tinh được phát triển cho sứ mệnh khoa học còn giúp dự báo bão, lập bản đồ cháy rừng và duy trì liên lạc ở vùng xa. Thách thức kỹ thuật có thể dẫn đến tiến bộ về vật liệu, cảm biến và hệ thống năng lượng, sau này được ứng dụng trong y học hay công nghiệp. Việc tìm kiếm sự sống ngoài Trái Đất cũng có thể thúc đẩy hợp tác quốc tế và tạo lý do hấp dẫn để người trẻ học vật lý, tin học và toán.', focusVi: 'Thân bài 1 nêu đóng góp khoa học, ứng dụng vệ tinh, đổi mới và giáo dục.' },
      { en: 'The objections are substantial: a launch programme can cost billions while public hospitals or schools lack basic resources. Missions may fail, and rockets generate emissions; collisions in orbit also add to the growing problem of space debris. Benefits from commercial research can be concentrated in a few companies, even when public money helped fund it. These concerns justify clear spending limits, environmental standards and agreements on sharing scientific data. They do not require abandoning exploration, but they do require showing that a mission has a credible public purpose.', vi: 'Những phản đối là đáng kể: chương trình phóng tàu có thể tốn hàng tỷ trong khi bệnh viện hay trường công thiếu nguồn lực cơ bản. Sứ mệnh có thể thất bại, tên lửa tạo phát thải, còn va chạm trên quỹ đạo làm tăng vấn đề rác không gian. Lợi ích từ nghiên cứu thương mại có thể tập trung ở vài công ty dù tiền công góp phần tài trợ. Những lo ngại này biện minh cho giới hạn chi tiêu rõ ràng, tiêu chuẩn môi trường và thoả thuận chia sẻ dữ liệu khoa học. Chúng không đòi hỏi từ bỏ khám phá, nhưng yêu cầu chứng minh sứ mệnh có mục đích công đáng tin cậy.', focusVi: 'Thân bài 2 phân tích ngân sách, tác động môi trường và câu hỏi về chia sẻ lợi ích.' },
      { en: 'Space research should not receive unlimited funding, yet its scientific and practical returns can extend well beyond the mission itself. Satellites already support services on which people rely, and exploration can stimulate knowledge and technology unavailable through other research. If governments set priorities openly and make public benefits a condition of support, these returns outweigh the risks and opportunity costs.', vi: 'Nghiên cứu không gian không nên nhận ngân sách vô hạn, nhưng lợi ích khoa học và thực tiễn có thể vượt xa bản thân sứ mệnh. Vệ tinh hiện hỗ trợ những dịch vụ mà mọi người dựa vào, còn hoạt động khám phá có thể thúc đẩy tri thức và công nghệ khó đạt được qua nghiên cứu khác. Nếu chính phủ công khai ưu tiên và yêu cầu lợi ích công làm điều kiện hỗ trợ, những kết quả này lớn hơn rủi ro và chi phí cơ hội.', focusVi: 'Kết luận xác định giới hạn đầu tư và khẳng định lợi ích công có điều kiện.' },
    ],
    vocabulary: [
      { phrase: 'scientific missions', meaningVi: 'các sứ mệnh khoa học', noteVi: 'Cụm chỉ hoạt động nghiên cứu được tổ chức theo nhiệm vụ cụ thể.' },
      { phrase: 'space debris', meaningVi: 'rác thải không gian', noteVi: 'Mảnh vỡ nhân tạo còn lại trên quỹ đạo.' },
      { phrase: 'opportunity costs', meaningVi: 'chi phí cơ hội', noteVi: 'Giá trị của phương án khác bị bỏ qua khi chọn một khoản đầu tư.' },
    ],
  },
  {
    id: 'sample-t2-extra-advantages-family', topicSlug: 'family', topicEn: 'Family', topicVi: 'Gia đình',
    title: 'Grandparents caring for young children',
    promptText: 'In many families, grandparents provide regular care for young children while parents work. Do the advantages of this arrangement outweigh the disadvantages?',
    paragraphs: [
      { en: 'Grandparents often help care for young children, especially when parents work long or irregular hours. This arrangement can provide trust and continuity, but it may also place pressure on older relatives and create disagreements about childcare. Overall, I believe the advantages outweigh the disadvantages when the help is voluntary, clearly discussed and supported by other forms of care where necessary.', vi: 'Ông bà thường giúp chăm sóc trẻ nhỏ, nhất là khi cha mẹ làm việc nhiều giờ hoặc theo ca thất thường. Cách sắp xếp này có thể đem lại sự tin tưởng và ổn định, nhưng cũng gây áp lực lên người lớn tuổi và nảy sinh bất đồng về cách nuôi dạy. Nhìn chung, tôi cho rằng lợi ích lớn hơn bất lợi nếu việc giúp đỡ là tự nguyện, được trao đổi rõ ràng và có hình thức chăm sóc khác hỗ trợ khi cần.', focusVi: 'Mở bài giới thiệu hình thức, nhận diện lợi ích và nguy cơ, nêu điều kiện đồng thuận.' },
      { en: 'Children may feel secure with relatives they already know, and grandparents can pass on family stories, language and traditions through everyday interaction. Parents may avoid the high cost of full-time childcare and gain a more dependable schedule than relying on occasional arrangements. For grandparents who want an active role, time with grandchildren can be meaningful and help sustain close ties between generations. The care can also be more responsive to a child’s habits than a large setting, particularly during illness or the transition into school.', vi: 'Trẻ có thể cảm thấy an tâm với người thân mình đã quen, còn ông bà có thể truyền lại chuyện gia đình, ngôn ngữ và truyền thống qua tương tác hằng ngày. Cha mẹ có thể tránh chi phí cao của dịch vụ chăm sóc toàn thời gian và có lịch trình ổn định hơn so với việc sắp xếp ngẫu nhiên. Với ông bà mong muốn có vai trò tích cực, thời gian bên cháu có thể đem lại ý nghĩa và duy trì gắn kết giữa các thế hệ. Sự chăm sóc cũng có thể đáp ứng thói quen của trẻ sát hơn so với môi trường đông người, đặc biệt khi trẻ ốm hoặc bắt đầu đi học.', focusVi: 'Thân bài 1 giải thích lợi ích tình cảm, văn hoá và tính linh hoạt cho cả gia đình.' },
      { en: 'However, regular childcare is demanding, and older people may have health, mobility or work commitments of their own. Parents might assume that help is always available, leaving grandparents unable to decline without family tension. Different views about sleep, food or discipline can also confuse a child unless adults communicate consistently. Families should agree on hours, responsibilities and expenses in advance, and parents need a backup plan. This protects grandparents’ independence and prevents an affectionate family role from becoming unpaid work with no limits.', vi: 'Tuy nhiên, chăm trẻ thường xuyên đòi hỏi nhiều công sức, trong khi người lớn tuổi có thể có vấn đề sức khoẻ, đi lại hoặc công việc riêng. Cha mẹ có thể mặc định rằng ông bà luôn sẵn sàng, khiến họ khó từ chối mà không gây căng thẳng gia đình. Quan điểm khác nhau về giấc ngủ, thức ăn hay kỷ luật cũng có thể khiến trẻ bối rối nếu người lớn không trao đổi nhất quán. Gia đình nên thống nhất trước giờ giấc, trách nhiệm và chi phí, còn cha mẹ cần có phương án dự phòng. Điều này bảo vệ sự độc lập của ông bà và tránh để vai trò tình cảm biến thành công việc không lương vô giới hạn.', focusVi: 'Thân bài 2 nêu gánh nặng và bất đồng, sau đó đề xuất ranh giới và phương án thay thế.' },
      { en: 'Care by grandparents can be a warm and practical arrangement, but it should remain a choice rather than an expectation. When families share duties fairly and respect older relatives’ limits, children gain close relationships while parents obtain dependable support. These benefits outweigh the disadvantages in many households, provided everyone can speak openly and no one is left carrying the burden alone.', vi: 'Ông bà chăm cháu có thể là cách sắp xếp ấm áp và thiết thực, nhưng nên là lựa chọn chứ không phải nghĩa vụ mặc định. Khi gia đình chia sẻ trách nhiệm công bằng và tôn trọng giới hạn của người lớn tuổi, trẻ có thêm quan hệ thân thiết còn cha mẹ nhận được hỗ trợ ổn định. Trong nhiều gia đình, lợi ích lớn hơn bất lợi nếu mọi người có thể trao đổi thẳng thắn và không ai phải gánh vác một mình.', focusVi: 'Kết luận khẳng định lợi ích khi dựa trên tự nguyện, công bằng và trao đổi cởi mở.' },
    ],
    vocabulary: [
      { phrase: 'continuity of care', meaningVi: 'sự chăm sóc liên tục, ổn định', noteVi: 'Cụm nhấn mạnh người chăm sóc quen thuộc và nhất quán.' },
      { phrase: 'backup plan', meaningVi: 'phương án dự phòng', noteVi: 'Dùng cho kế hoạch thay thế khi lịch chăm sóc thay đổi.' },
      { phrase: 'share duties fairly', meaningVi: 'chia sẻ trách nhiệm công bằng', noteVi: 'Cụm hữu ích khi bàn về phân chia công việc trong gia đình.' },
    ],
  },
  {
    id: 'sample-t2-extra-advantages-economy', topicSlug: 'economy', topicEn: 'Economy', topicVi: 'Kinh tế',
    title: 'Automation in manufacturing',
    promptText: 'Factories are replacing more human labour with automated machines and robots. Do the advantages of this change outweigh the disadvantages?',
    paragraphs: [
      { en: 'Automation is changing factories by allowing machines to perform tasks that workers once completed by hand. It can raise productivity and improve safety, yet it may remove jobs and concentrate gains among owners of technology. I believe the advantages outweigh the disadvantages over time if businesses share productivity gains and governments help affected employees retrain for emerging roles.', vi: 'Tự động hoá đang làm thay đổi nhà máy khi máy móc đảm nhận nhiệm vụ mà trước đây công nhân làm thủ công. Nó có thể tăng năng suất và cải thiện an toàn, nhưng cũng có thể làm mất việc và tập trung lợi ích vào chủ sở hữu công nghệ. Tôi cho rằng lợi ích dài hạn lớn hơn bất lợi nếu doanh nghiệp chia sẻ thành quả năng suất và chính phủ hỗ trợ nhân viên bị ảnh hưởng học lại để đảm nhiệm công việc mới.', focusVi: 'Mở bài giới thiệu chuyển đổi, cân nhắc tác động lao động và nêu điều kiện phân phối lợi ích.' },
      { en: 'Robots can carry out repetitive or hazardous operations consistently, reducing errors and injuries in tasks such as lifting heavy materials or handling dangerous chemicals. Factories can produce more goods with less downtime, which may lower costs and make domestic firms more competitive. Automation also creates demand for technicians, programmers and maintenance specialists. If manufacturers expand successfully, they may hire people into these higher-skilled roles and support suppliers, logistics firms and other businesses connected to production.', vi: 'Robot có thể thực hiện ổn định các thao tác lặp đi lặp lại hoặc nguy hiểm, giảm lỗi và chấn thương trong công việc như nâng vật liệu nặng hay xử lý hoá chất nguy hiểm. Nhà máy có thể sản xuất nhiều hàng hơn với ít thời gian ngừng hoạt động, từ đó hạ chi phí và giúp doanh nghiệp trong nước cạnh tranh tốt hơn. Tự động hoá cũng tạo nhu cầu cho kỹ thuật viên, lập trình viên và chuyên gia bảo trì. Nếu nhà sản xuất phát triển thành công, họ có thể tuyển người vào những vị trí kỹ năng cao hơn, đồng thời hỗ trợ nhà cung cấp, công ty logistics và doanh nghiệp liên quan đến sản xuất.', focusVi: 'Thân bài 1 nêu lợi ích năng suất, an toàn và việc làm kỹ năng cao.' },
      { en: 'The transition can be painful for employees whose skills are tied to a task that machines can now perform. A worker may not be able to move immediately into a technical position, and a factory town can lose income if many jobs disappear at once. The gains may also flow mainly to shareholders unless wages and training keep pace. Employers should give notice, fund relevant courses and consult staff before restructuring; public programmes can provide temporary income support and connect learners with real vacancies.', vi: 'Quá trình chuyển đổi có thể gây khó khăn cho nhân viên có kỹ năng gắn với công việc mà máy móc nay đảm nhận được. Một công nhân có thể chưa chuyển ngay sang vị trí kỹ thuật, và thị trấn công nghiệp có thể mất thu nhập nếu nhiều việc làm biến mất cùng lúc. Thành quả cũng có thể chủ yếu chảy vào cổ đông nếu lương và đào tạo không theo kịp. Nhà tuyển dụng nên báo trước, tài trợ khoá học phù hợp và tham vấn nhân viên trước khi tái cơ cấu; chương trình công có thể hỗ trợ thu nhập tạm thời và kết nối người học với vị trí tuyển dụng thực tế.', focusVi: 'Thân bài 2 nêu chi phí chuyển đổi với lao động và địa phương, kèm trách nhiệm hỗ trợ.' },
      { en: 'Automation can make production safer and more efficient, and its benefits can extend into new occupations and lower consumer prices. These gains do not arrive automatically for workers displaced by machinery. With serious retraining and a fairer share of productivity improvements, the economic advantages are greater than the disadvantages; without such measures, the transition risks deepening insecurity and inequality.', vi: 'Tự động hoá có thể khiến sản xuất an toàn, hiệu quả hơn, và lợi ích có thể mở rộng sang ngành nghề mới cũng như giá tiêu dùng thấp hơn. Những lợi ích này không tự động đến với người lao động bị máy móc thay thế. Với đào tạo lại nghiêm túc và chia sẻ thành quả năng suất công bằng hơn, ưu điểm kinh tế lớn hơn bất lợi; nếu thiếu biện pháp như vậy, chuyển đổi có nguy cơ làm bất ổn và bất bình đẳng sâu sắc hơn.', focusVi: 'Kết luận nhắc tiềm năng kinh tế và gắn lập trường với hỗ trợ người lao động.' },
    ],
    vocabulary: [
      { phrase: 'repetitive operations', meaningVi: 'các thao tác lặp đi lặp lại', noteVi: 'Cụm mô tả nhóm nhiệm vụ thường được tự động hoá.' },
      { phrase: 'productivity gains', meaningVi: 'thành quả tăng năng suất', noteVi: 'Dùng khi nói về sản lượng cao hơn trên cùng nguồn lực.' },
      { phrase: 'income support', meaningVi: 'hỗ trợ thu nhập', noteVi: 'Khoản trợ giúp tạm thời trong giai đoạn chuyển đổi việc làm.' },
    ],
  },
];

